INSERT INTO agents (id, full_name, title, bio, phone, email, photo_url, expertise, sort_order) VALUES
    (1, 'Selin Arıkan', 'Boğaz Hattı Danışmanı', 'İstanbul’un kuzey kıyısında, arsa ve yapı ölçeğini aynı titizlikle okur. Bebek, Arnavutköy ve Kandilli’de uzun yıllardır çalışır.', '0212 255 18 40', 'selin.arikan@avelrune.com', '/images/agents/selin.jpg', 'İstanbul Boğaz hattı', 1),
    (2, 'Deniz Koray', 'Ege Kıyısı Danışmanı', 'Bodrum yarımadasında arazi eğimini, rüzgârı ve komşuluk mesafesini yerinde değerlendirir. Villa alımında acele etmez.', '0252 317 44 12', 'deniz.koray@avelrune.com', '/images/agents/deniz.jpg', 'Bodrum ve Güney Ege', 2),
    (3, 'Miraç Elvan', 'İzmir ve Çeşme Danışmanı', 'Urla, Alaçatı ve Alsancak’ta hem taş yapı hem çağdaş konut stokunu izler. Kiralama süreçlerini sakin yürütür.', '0232 463 09 70', 'mirac.elvan@avelrune.com', '/images/agents/mirac.jpg', 'İzmir, Urla, Çeşme', 3),
    (4, 'Aylin Sönmez', 'Akdeniz Danışmanı', 'Antalya ve Kaş hattında deniz mesafesi, gürültü ve gün ışığını yerinde ölçer. Yatırım ile yaşam kararını ayırır.', '0242 248 61 30', 'aylin.sonmez@avelrune.com', '/images/agents/aylin.jpg', 'Antalya ve Akdeniz', 4);
INSERT INTO properties (id, title, slug, description, price, listing_type, property_type, city, district, neighborhood, gross_area, net_area, room_count, building_age, floor, total_floors, heating_type, furnished, latitude, longitude, featured, active, features, agent_id, assigned_user_id, created_at, updated_at) VALUES
    (1, 'Bebek’te Boğaz Manzaralı 4+1 Daire', 'bebek-te-bogaz-manzarali-4-1-daire', 'Bebek yokuşunun sakin bir sokağında, Boğaz’a bakan bu daire 1970’lerin ölçülü mimarisini koruyor. Salonun uzun pencere hattı suyu gün boyu içeri alıyor; mutfak ise avluya bakacak şekilde yeniden düzenlendi. Oda oranları gösterişten uzak, kullanılabilir. Bina cephesi yakın dönemde onarıldı, ortak alanlar sade tutuldu.', 87500000, 'SALE', 'APARTMENT', 'İstanbul', 'Beşiktaş', 'Bebek', 245, 210, '4+1', 8, 4, 6, 'FLOOR_HEATING', FALSE, 41.0776, 29.0434, TRUE, TRUE, 'Boğaz manzarası|Asansör|Açık otopark|Güvenlik|Ankastre mutfak|Ebeveyn banyosu', 1, 2, TIMESTAMPTZ '2026-01-01 00:00:00+00', TIMESTAMPTZ '2026-01-01 00:00:00+00'),
    (2, 'Etiler’de Modern Rezidans Dairesi', 'etiler-de-modern-rezidans-dairesi', 'Nispetiye’ye yürüme mesafesinde, yüksek katlı bir yapıda güney-batı cepheli daire. Salon ve yemek alanı tek hacimde; çalışma odası ayrı tutulmuş. Rezidansın zemin katında yüzme alanı ve sessiz bir çalışma salonu var. Manzara Boğaz’ın tamamını göstermiyor, buna karşılık şehir dokusu net ve düzenli.', 46200000, 'SALE', 'RESIDENCE', 'İstanbul', 'Beşiktaş', 'Etiler', 186, 158, '3+1', 4, 12, 22, 'CENTRAL', FALSE, 41.0819, 29.0348, TRUE, TRUE, 'Yüzme alanı|Kapalı otopark|7/24 güvenlik|Jeneratör|Akıllı ev|Çamaşır odası', 1, 2, TIMESTAMPTZ '2026-01-01 00:00:00+00', TIMESTAMPTZ '2026-01-01 00:00:00+00'),
    (3, 'Sarıyer’de Müstakil Villa', 'sariyer-de-mustakil-villa', 'Yeniköy sırtlarında, ağaçlarla çevrili bir parselde üç katlı müstakil villa. Zemin kat yaşam alanına, üst katlar yatak odalarına ayrılmış. Bahçe abartılı peyzajdan kaçınılarak çim, zeytin ve birkaç meyve ağacıyla bırakılmış. Garaj iki araca uygun. İçeride merdiven boşluğu gün ışığını aşağıya indiriyor.', 128500000, 'SALE', 'VILLA', 'İstanbul', 'Sarıyer', 'Yeniköy', 420, 365, '5+1', 12, 0, 3, 'FLOOR_HEATING', FALSE, 41.1194, 29.0702, TRUE, TRUE, 'Özel bahçe|Kapalı garaj|Şömine|Ebeveyn süiti|Depo|Jeneratör', 1, 2, TIMESTAMPTZ '2026-01-01 00:00:00+00', TIMESTAMPTZ '2026-01-01 00:00:00+00'),
    (4, 'Ataşehir’de Yüksek Kat Rezidans', 'atasehir-de-yuksek-kat-rezidans', 'Finans merkezine bakan cephede, 27. katta kiralık daire. Mobilya seçimi nötr; uzun süreli kullanıma uygun. Mutfak salona açık, ikinci oda çalışma veya misafir için yeterli. Bina içindeki sosyal alanlar kalabalık saatlerde doluyor, buna karşılık dairenin kendisi sessiz.', 125000, 'RENT', 'RESIDENCE', 'İstanbul', 'Ataşehir', 'Batı Ataşehir', 142, 124, '2+1', 6, 27, 40, 'CENTRAL', TRUE, 40.9923, 29.1244, FALSE, TRUE, 'Eşyalı|Kapalı otopark|Yüzme alanı|Güvenlik|Klima|Balkon', 1, 2, TIMESTAMPTZ '2026-01-01 00:00:00+00', TIMESTAMPTZ '2026-01-01 00:00:00+00'),
    (5, 'Nişantaşı’nda Yenilenmiş Apartman Dairesi', 'nisantasi-nda-yenilenmis-apartman-dairesi', 'Teşvikiye’nin ara sokaklarından birinde, 1930’ların apartmanında kat yüksekliği korunarak yenilenmiş daire. Parke orijinal; ıslak hacimler yeniden kuruldu. Salon sokağa, yatak odaları avluya bakıyor. Asansör sonradan eklenmiş, kabin dar. Bina sakin, kapıcı düzeni sürüyor.', 38900000, 'SALE', 'APARTMENT', 'İstanbul', 'Şişli', 'Nişantaşı', 168, 145, '3+1', 46, 3, 6, 'COMBI', FALSE, 41.0486, 28.9951, FALSE, TRUE, 'Yüksek tavan|Asansör|Kapıcı|Ankastre mutfak|Kiler|Güney cephe', 1, 2, TIMESTAMPTZ '2026-01-01 00:00:00+00', TIMESTAMPTZ '2026-01-01 00:00:00+00'),
    (6, 'Kandilli’de Yalı Dairesi', 'kandilli-de-yali-dairesi', 'Kandilli yalı sırasının bir parçasında, suya yakın katta dört odalı daire. Tavanlar yüksek, pencere ritmi eski yapıya ait. Mutfak çağdaş; salondaki şömine çalışır durumda. Ortak iskele kullanımı var, özel rıhtım yok. Yapı yakın dönemde güçlendirildi, iç bölünme özgün plana yakın duruyor.', 156000000, 'SALE', 'YALI', 'İstanbul', 'Üsküdar', 'Kandilli', 210, 188, '4+1', 18, 1, 3, 'FLOOR_HEATING', FALSE, 41.0752, 29.0586, TRUE, TRUE, 'Deniz manzarası|Ortak iskele|Şömine|Yüksek tavan|Güvenlik|Bahçe kullanımı', 1, 2, TIMESTAMPTZ '2026-01-01 00:00:00+00', TIMESTAMPTZ '2026-01-01 00:00:00+00'),
    (7, 'Beykoz’da Orman Kenarı Villa', 'beykoz-da-orman-kenari-villa', 'Paşabahçe sırtında, orman sınırına komşu iki katlı villa. Yaşam alanı bahçeye açılıyor; üst katta dört yatak odası var. Isı yalıtımı yenilendi. Yol eğimli, kışın dikkat istiyor. Manzara parça parça Boğaz ve yeşil. Komşuluk seyrek, gece sessiz.', 64500000, 'SALE', 'VILLA', 'İstanbul', 'Beykoz', 'Paşabahçe', 380, 320, '5+2', 9, 0, 2, 'COMBI', FALSE, 41.1167, 29.0931, FALSE, TRUE, 'Geniş bahçe|Kapalı garaj|Şömine|Ebeveyn banyosu|Depo|Jeneratör', 1, 2, TIMESTAMPTZ '2026-01-01 00:00:00+00', TIMESTAMPTZ '2026-01-01 00:00:00+00'),
    (8, 'Yalıkavak’ta Deniz Manzaralı Villa', 'yalikavak-ta-deniz-manzarali-villa', 'Yalıkavak koyuna bakan yamaçta, terasların denize doğru kademelendiği villa. Havuz rüzgârdan kısmen korunaklı. İç mekân taş ve ahşapla tutulmuş; salon tek büyük hacim. Üst katta ebeveyn odası ayrı bir teras alıyor. Marina’ya araçla kısa mesafe. Parsel eğimli olduğu için bahçe düz değil, buna karşılık görüş kesintisiz.', 198000000, 'SALE', 'VILLA', 'Muğla', 'Bodrum', 'Yalıkavak', 510, 430, '6+1', 7, 0, 3, 'AIR_CONDITIONING', FALSE, 37.1058, 27.2906, TRUE, TRUE, 'Sonsuzluk havuzu|Deniz manzarası|Akıllı ev|Jeneratör|Kapalı garaj|Personel odası', 2, 2, TIMESTAMPTZ '2026-01-01 00:00:00+00', TIMESTAMPTZ '2026-01-01 00:00:00+00'),
    (9, 'Türkbükü’nde Özel Havuzlu Villa', 'turkbuku-nde-ozel-havuzlu-villa', 'Türkbükü’nün iç kesiminde, koy manzarasını ağaçlar arasından alan villa. Havuz evi ve ana yapı aynı kotu paylaşmıyor; bu sayede yaşam alanı görece mahrem. Yaz kullanımı için döşenmiş, kışın da ısınabiliyor. Plaja inen yol dar. Komşular yazın çoğalıyor, kışın evler kapanıyor.', 112000000, 'SALE', 'VILLA', 'Muğla', 'Bodrum', 'Türkbükü', 360, 305, '4+1', 5, 0, 2, 'AIR_CONDITIONING', TRUE, 37.1224, 27.3772, TRUE, TRUE, 'Özel havuz|Eşyalı|Bahçe|Jeneratör|Klima|Açık mutfak', 2, 2, TIMESTAMPTZ '2026-01-01 00:00:00+00', TIMESTAMPTZ '2026-01-01 00:00:00+00'),
    (10, 'Gümüşlük’te Taş Villa', 'gumusluk-te-tas-villa', 'Gümüşlük çarşıya yakın, taş duvarlı iki katlı ev. Alt kat gölge ve serin; üst kat teras deniz yönüne bakıyor. Kiralama dönemi yıllık. Mobilya sade, hepsi evle birlikte duruyor. Yaz akşamları çarşı sesi geliyor, odalar buna rağmen kullanılabilir durumda.', 180000, 'RENT', 'STONE_HOUSE', 'Muğla', 'Bodrum', 'Gümüşlük', 220, 185, '3+1', 14, 0, 2, 'AIR_CONDITIONING', TRUE, 37.0547, 27.2378, FALSE, TRUE, 'Taş yapı|Teras|Eşyalı|Klima|Bahçe|Şömine', 2, 2, TIMESTAMPTZ '2026-01-01 00:00:00+00', TIMESTAMPTZ '2026-01-01 00:00:00+00'),
    (11, 'Alaçatı’da Taş Ev', 'alacati-da-tas-ev', 'Alaçatı’nın yerleşik dokusunda, avlulu taş ev. Sokak cephesi sade, yaşam avluya açılıyor. Çatı katı çalışma ve misafir için ayrılmış. İç sıvalar yenilendi, özgün taş yüzeyler yer yer açık bırakıldı. Yazın merkez kalabalık; ev bir sokak geride kaldığı için gürültü ölçülü.', 42800000, 'SALE', 'STONE_HOUSE', 'İzmir', 'Çeşme', 'Alaçatı', 195, 168, '3+1', 22, 0, 2, 'COMBI', FALSE, 38.2826, 26.3744, TRUE, TRUE, 'İç avlu|Taş duvar|Şömine|Teras|Kiler|Klima', 3, 2, TIMESTAMPTZ '2026-01-01 00:00:00+00', TIMESTAMPTZ '2026-01-01 00:00:00+00'),
    (12, 'Ilıca’da Deniz Kenarı Daire', 'ilica-da-deniz-kenari-daire', 'Ilıca sahiline yakın, dört katlı sakin bir yapıda ikinci kat. Salon balkonu kumsal yönüne bakıyor, mesafe kısa. Yaz kiralama değil, yıllık sözleşme. Eşyalar yeterli ve yıpranmamış. Bina asansörsüz; merdiven geniş. Kışın site neredeyse boşalıyor, ısınma klima ile sağlanıyor.', 95000, 'RENT', 'APARTMENT', 'İzmir', 'Çeşme', 'Ilıca', 128, 110, '2+1', 11, 2, 4, 'AIR_CONDITIONING', TRUE, 38.3079, 26.3751, FALSE, TRUE, 'Denize yakın|Eşyalı|Balkon|Klima|Güvenlik|Otopark', 3, 2, TIMESTAMPTZ '2026-01-01 00:00:00+00', TIMESTAMPTZ '2026-01-01 00:00:00+00'),
    (13, 'Urla’da Müstakil Bahçeli Ev', 'urla-da-mustakil-bahceli-ev', 'Urla İskele’ye yakın, zeytinli bir bahçede müstakil ev. Zemin kat yaşam, üst kat yatak odaları. Mutfak bahçeye doğrudan açılıyor. Yapı bakımlı, çatı yakın dönemde yenilendi. Deniz manzarası yok; bunun yerine bahçe ve sessizlik var. İzmir merkezine mesafe günlük gidip gelmeye uygun.', 27500000, 'SALE', 'HOUSE', 'İzmir', 'Urla', 'İskele', 240, 205, '4+1', 16, 0, 2, 'COMBI', FALSE, 38.3221, 26.7648, TRUE, TRUE, 'Zeytin bahçesi|Müstakil|Şömine|Kapalı garaj|Depo|Güneş enerjisi', 3, 2, TIMESTAMPTZ '2026-01-01 00:00:00+00', TIMESTAMPTZ '2026-01-01 00:00:00+00'),
    (14, 'Alsancak’ta Loft Daire', 'alsancak-ta-loft-daire', 'Kıbrıs Şehitleri’ne yakın, yenilenmiş bir apartmanda yüksek tavanlı 1+1. Salon ve yatak alanı cam bölme ile ayrılmış. Kiralık, eşyalı. Asansör var. Sokak hareketli; gece sesi ikinci odaya daha az ulaşıyor. Kısa süreli turistik kiralama yapılmıyor.', 72000, 'RENT', 'APARTMENT', 'İzmir', 'Konak', 'Alsancak', 96, 88, '1+1', 3, 5, 7, 'COMBI', TRUE, 38.4361, 27.1428, FALSE, TRUE, 'Yüksek tavan|Eşyalı|Asansör|Ankastre mutfak|Klima|Güvenlik', 3, 2, TIMESTAMPTZ '2026-01-01 00:00:00+00', TIMESTAMPTZ '2026-01-01 00:00:00+00'),
    (15, 'Lara’da Deniz Manzaralı Rezidans', 'lara-da-deniz-manzarali-rezidans', 'Lara sahil şeridine paralel, dokuzuncu katta güney cepheli daire. Salon camı denizi kesintisiz alıyor. Mutfak kapalı tutulmuş. Site içinde yürüyüş alanı ve kapalı otopark var. Yazın çevrede otel hareketi artıyor, bina içi düzen korunuyor.', 31800000, 'SALE', 'RESIDENCE', 'Antalya', 'Muratpaşa', 'Lara', 174, 152, '3+1', 5, 9, 16, 'CENTRAL', FALSE, 36.8512, 30.7571, TRUE, TRUE, 'Deniz manzarası|Kapalı otopark|Yüzme alanı|Güvenlik|Balkon|Jeneratör', 4, 2, TIMESTAMPTZ '2026-01-01 00:00:00+00', TIMESTAMPTZ '2026-01-01 00:00:00+00'),
    (16, 'Kaş’ta Taş Ev', 'kas-ta-tas-ev', 'Kaş merkezin üst kotunda, eğimli bir parselde taş ev. Teras Kekova yönüne bakıyor. Odalar küçük tutulmuş, yaşam teras ve mutfakta toplanıyor. Araç parkı sokakta. Yazın merkeze inmek kısa, kışın ev kendi başına duruyor. Çatı ahşap, bakımı yapılmış.', 24900000, 'SALE', 'STONE_HOUSE', 'Antalya', 'Kaş', 'Andifli', 160, 138, '3+1', 28, 0, 2, 'AIR_CONDITIONING', FALSE, 36.1995, 29.64, FALSE, TRUE, 'Deniz manzarası|Teras|Taş yapı|Klima|Şömine|Bahçe', 4, 2, TIMESTAMPTZ '2026-01-01 00:00:00+00', TIMESTAMPTZ '2026-01-01 00:00:00+00'),
    (17, 'Göcek’te Deniz Manzaralı Villa', 'gocek-te-deniz-manzarali-villa', 'Göcek koyuna bakan, havuzlu villa. Yıllık kiralama. İç mekân yazlık karakterde, bakımlı. Alt kat salon ve mutfak, üst kat odalar. Marina ve çarşıya araçla birkaç dakika. Kışın ısınma klima ve şömine ile. Bahçe bakımı aidata dahil.', 210000, 'RENT', 'VILLA', 'Muğla', 'Fethiye', 'Göcek', 290, 248, '4+1', 8, 0, 2, 'AIR_CONDITIONING', TRUE, 36.7548, 28.9437, FALSE, TRUE, 'Özel havuz|Eşyalı|Deniz manzarası|Jeneratör|Kapalı garaj|Klima', 4, 2, TIMESTAMPTZ '2026-01-01 00:00:00+00', TIMESTAMPTZ '2026-01-01 00:00:00+00'),
    (18, 'Bebek’te Kiralık 3+1 Daire', 'bebek-te-kiralik-3-1-daire', 'Bebek caddesine paralel sakin bir sokakta, ikinci kat kiralık daire. Eşyalar yeni değil, düzenli. Salon balkonu ağaçlara bakıyor, Boğaz görünmüyor. Bina küçük, asansör yok. Uzun dönem kiralama tercih ediliyor. Market ve durak yürüme mesafesinde.', 165000, 'RENT', 'APARTMENT', 'İstanbul', 'Beşiktaş', 'Bebek', 155, 132, '3+1', 15, 2, 5, 'COMBI', TRUE, 41.0768, 29.0441, FALSE, TRUE, 'Eşyalı|Balkon|Ankastre mutfak|Doğalgaz|Kapıcı|Güney cephe', 1, 2, TIMESTAMPTZ '2026-01-01 00:00:00+00', TIMESTAMPTZ '2026-01-01 00:00:00+00');
